import { APIGatewayProxyResult } from 'aws-lambda';
import { Meta, ResponseOptions, ApiResponseBody, Message, ErrorBody } from '../types/core-types';

function corsHeaders() {
  return {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers':
      'Content-Type,Authorization,X-Correlation-Id,X-Requested-With',
    'Access-Control-Allow-Methods': 'GET,POST,PUT,DELETE,PATCH,OPTIONS',
  };
}

function now() {
  return new Date().toISOString();
}

function buildMeta(options: ResponseOptions): Meta {
  return {
    correlationId: options.correlationId,
    timestamp: now(),
    version: 'v1',
  };
}

function createResponse<T>(
  statusCode: number,
  body: ApiResponseBody<T>,
  headers?: Record<string, string>,
): APIGatewayProxyResult {

  return {
    statusCode,
    headers: {
      'Content-Type': 'application/json',
      ...corsHeaders(),
      ...(headers ?? {}),
    },
    body: JSON.stringify(body),
  };
}

/**
 * Normalize response data
 * Arrays become { items: [] }
 */
function normalizeData<T>(data: T | null): any {
  if (Array.isArray(data)) {
    return { items: data };
  }
  return data ?? null;
}

export class ApiResponse {

  static ok<T>(
    data: T | null,
    message: Message | string,
    options: ResponseOptions,
  ): APIGatewayProxyResult {

    const body: ApiResponseBody<T> = {
      success: true,
      statusCode: 200,
      message: typeof message === 'string' ? { title: message, description: message, severity: 'SUCCESS' } : message,
      data: normalizeData(data),
      error: null,
      meta: buildMeta(options),
    };

    if (options.fhir !== undefined) {
      body.fhir = options.fhir;
    }

    if (options.fhirValidation !== undefined) {
      body.fhirValidation = options.fhirValidation;
    }

    return createResponse(200, body, options.headers);
  }

  static created<T>(
    data: T | null,
    message: Message | string ,
    options: ResponseOptions,
  ): APIGatewayProxyResult {

    return createResponse(
      201,
      {
        success: true,
        statusCode: 201,
        message: typeof message === 'string' ? { title: message, description: message, severity: 'SUCCESS' } : message,
        data: normalizeData(data),
        error: null,
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  static badRequest(
    message: any | Message,
    options: ResponseOptions,
    error?: ErrorBody,
  ): APIGatewayProxyResult {

    return createResponse(
      400,
      {
        success: false,
        statusCode: 400,
        message,
        data: null,
        error: error ?? { code: 'BAD_REQUEST' },
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  static unauthorized(
    message: any | Message,
    options: ResponseOptions,
    error?: ErrorBody,
  ): APIGatewayProxyResult {

    return createResponse(
      401,
      {
        success: false,
        statusCode: 401,
        message,
        data: null,
        error: error ?? { code: 'UNAUTHORIZED' },
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  static forbidden(
    message: Message,
    options: ResponseOptions,
    error?: ErrorBody,
  ): APIGatewayProxyResult {

    return createResponse(
      403,
      {
        success: false,
        statusCode: 403,
        message,
        data: null,
        error: error ?? { code: 'FORBIDDEN' },
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  static notFound(
    message: any | Message,
    options: ResponseOptions,
    error?: ErrorBody,
  ): APIGatewayProxyResult {

    return createResponse(
      404,
      {
        success: false,
        statusCode: 404,
        message,
        data: null,
        error: error ?? { code: 'NOT_FOUND' },
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  static conflict(
    message: Message,
    options: ResponseOptions,
    error?: ErrorBody,
  ): APIGatewayProxyResult {

    return createResponse(
      409,
      {
        success: false,
        statusCode: 409,
        message,
        data: null,
        error: error ?? { code: 'CONFLICT' },
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  /** 409 with success envelope and populated `data` (e.g. idempotent create replay). */
  static conflictWithData<T>(
    data: T,
    message: Message,
    options: ResponseOptions,
  ): APIGatewayProxyResult {
    return createResponse(
      409,
      {
        success: true,
        statusCode: 409,
        message,
        data: normalizeData(data),
        error: null,
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  static unprocessableEntity(
    message: any | Message,
    options: ResponseOptions,
    error?: ErrorBody,
  ): APIGatewayProxyResult {
    return createResponse(
      422,
      {
        success: false,
        statusCode: 422,
        message,
        data: null,
        error: error ?? { code: 'UNPROCESSABLE_ENTITY' },
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  static internalServerError(
    message: any | Message,
    options: ResponseOptions,
    error?: ErrorBody,
  ): APIGatewayProxyResult {

    return createResponse(
      500,
      {
        success: false,
        statusCode: 500,
        message,
        data: null,
        error: error ?? { code: 'INTERNAL_ERROR' },
        meta: buildMeta(options),
      },
      options.headers
    );
  }

  /** Generic error response for any status code (e.g. 400, 401, 403, 404, 409, 500). */
  static error(
    statusCode: number,
    message: any | Message,
    options: ResponseOptions,
    error?: ErrorBody,
  ): APIGatewayProxyResult {
    return createResponse(
      statusCode,
      {
        success: false,
        statusCode,
        message,
        data: null,
        error: error ?? { code: 'ERROR' },
        meta: buildMeta(options),
      },
      options.headers
    );
  }
}